// Supabase Database Webhook payload
// Формат: { type: 'UPDATE', table: 'leads', record: {...}, old_record: {...} }

const payload = $input.first().json.body || $input.first().json;

const record = payload.record || payload;
const oldRecord = payload.old_record || {};

// Проверяем что это leads и статус изменился
if (payload.table && payload.table !== 'leads') {
  return { json: { skip: true, reason: 'Not leads table' } };
}

const newStatus = record.status;
const oldStatus = oldRecord.status;

// Если статус не изменился - пропускаем
if (newStatus === oldStatus) {
  return { json: { skip: true, reason: 'Status not changed' } };
}

// Маппинг статусов на события CAPI
const statusToEvent = {
  // Диагностика
  'diagnostic_scheduled': 'Schedule',
  'scheduled': 'Schedule',
  'booked': 'Schedule',
  'diagnostic': 'Schedule',
  // Продажа
  'sold': 'Purchase',
  'sale': 'Purchase',
  'won': 'Purchase',
  'closed_won': 'Purchase',
  'paid': 'Purchase',
};

const eventName = statusToEvent[newStatus];

if (!eventName) {
  return { json: { skip: true, reason: `Status '${newStatus}' not mapped to CAPI event` } };
}

// Формируем данные для CAPI
return {
  json: {
    skip: false,
    project_id: record.project_id,
    lead_id: record.id,
    event_name: eventName,
    event_time: Math.floor(Date.now() / 1000),
    value: record.deal_amount || record.revenue || 0,
    currency: 'RUB',
    // Дополнительно для логов
    old_status: oldStatus,
    new_status: newStatus,
  }
};

const result = $input.first().json;
return {
  json: {
    success: result.body?.success || false,
    event_name: $('Parse Status Change').first().json.event_name,
    lead_id: $('Parse Status Change').first().json.lead_id,
    old_status: $('Parse Status Change').first().json.old_status,
    new_status: $('Parse Status Change').first().json.new_status,
    capi_response: result.body
  }
};

return {
  json: {
    success: true,
    skipped: true,
    reason: $input.first().json.reason
  }
};
